
(() => {
  'use strict';
  const GAME_KEY='network-quest-progress-v1';
  const MASCOT="data:image/png;base64,";
  
const DAILY_GOAL = 5;
function emptyGame() { return {version:1,correct:[],days:{},sound:false}; }
function unique(values) { return [...new Set(values.filter(value=>typeof value==='string'))]; }
function normalizeGame(value) {
  if (!value || typeof value !== 'object') return emptyGame();
  const days = {};
  for (const [key,items] of Object.entries(value.days || {})) {
    if (/^\d{4}-\d{2}-\d{2}$/.test(key) && Array.isArray(items)) days[key]=unique(items);
  }
  return {version:1,correct:Array.isArray(value.correct)?unique(value.correct):[],days,sound:value.sound===true};
}
function mergeGame(left,right) {
  const a=normalizeGame(left),b=normalizeGame(right);
  const days={...a.days};
  for (const [date,items] of Object.entries(b.days)) days[date]=unique([...(days[date]||[]),...items]);
  return {version:1,correct:unique([...a.correct,...b.correct]),days,sound:a.sound};
}
function totalXP(game) {
  return game.correct.length*10+Object.values(game.days).filter(items=>items.length>=DAILY_GOAL).length*20;
}
function dayBefore(day) {
  return new Date(Date.parse(day+'T00:00:00Z')-86400000).toISOString().slice(0,10);
}
function currentStreak(game,today) {
  let day=(game.days[today]?.length||0)>=DAILY_GOAL?today:dayBefore(today);
  let count=0;
  while ((game.days[day]?.length||0)>=DAILY_GOAL) { count++; day=dayBefore(day); }
  return count;
}
function awardAttempts(game,attempts,today) {
  const next=normalizeGame(game);
  const before=totalXP(next);
  const wasComplete=(next.days[today]?.length||0)>=DAILY_GOAL;
  const todayIDs=new Set(next.days[today]||[]);
  const correct=new Set(next.correct);
  for (const attempt of attempts) {
    todayIDs.add(attempt.id);
    if (attempt.correct) correct.add(attempt.id);
  }
  next.days[today]=[...todayIDs];
  next.correct=[...correct];
  return {game:next,gain:totalXP(next)-before,goalReached:!wasComplete&&todayIDs.size>=DAILY_GOAL};
}

  const today=()=>{
    const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
    const get=type=>parts.find(part=>part.type===type).value;
    return get('year')+'-'+get('month')+'-'+get('day');
  };
  function readSaved() {
    try { return normalizeGame(JSON.parse(localStorage.getItem(GAME_KEY))); }
    catch { return emptyGame(); }
  }
  let game=readSaved();
  let writable=true;
  function persist() {
    try { localStorage.setItem(GAME_KEY,JSON.stringify(game)); }
    catch { writable=false; }
  }
  const tidy=text=>String(text||'').replace(/\s+/g,' ').trim();
  const knownQuestions=new Map();
  function questionID(prompt) {
    const text=tidy(prompt);
    if(knownQuestions.has(text))return knownQuestions.get(text);
    let hash=2166136261;
    for(let i=0;i<text.length;i++) hash=Math.imul(hash^text.charCodeAt(i),16777619);
    return 'prompt-'+(hash>>>0).toString(36);
  }
  const icon=(type)=>{
    const paths={
      star:'m12 3 2.8 5.7L21 10l-4.5 4.4 1.1 6.2L12 17.7l-5.6 2.9 1.1-6.2L3 10l6.2-1.3L12 3Z',
      fire:'M13 3c1 6-5 5-5 10 0 2 1 3 2 4-4-1-6-4-3-9-6 5-4 13 4 13 9 0 12-10 6-15 0 4-1 5-2 6 0-4-1-7-2-9Z',
      goal:'M21 12a9 9 0 1 1-9-9m5 1 3 3-8 8m-5-3a5 5 0 1 0 8-4',
      sound:'M4 9h4l5-4v14l-5-4H4V9Zm12-2c3 2 3 8 0 10m3-13c5 4 5 12 0 16'
    };
    return '<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+paths[type]+'"/></svg>';
  };
  const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||document.documentElement.dataset.motion==='off';
  document.addEventListener('DOMContentLoaded',()=>{
    const main=document.getElementById('main');
    if(!main)return;
    for(const chapter of window.CHAPTERS||[]) {
      for(const question of chapter.questions||[])knownQuestions.set(tidy(question.prompt),'question-'+question.id);
    }
    let pending=null;
    let frame=0;
    let redrawFrame=0;
    let toastTimer;
    let routeSizer;
    let audio;
    function playSound(kind) {
      if(!game.sound)return;
      try {
        const Audio=window.AudioContext||window.webkitAudioContext;
        if(!Audio)return;
        audio ||= new Audio();
        audio.resume().catch(()=>{});
        const notes=kind==='goal'?[523.25,659.25,783.99]:[659.25,880];
        notes.forEach((frequency,index)=>{
          const oscillator=audio.createOscillator();
          const gain=audio.createGain();
          oscillator.type='sine'; oscillator.frequency.value=frequency;
          const start=audio.currentTime+index*.11;
          gain.gain.setValueAtTime(0,start);
          gain.gain.linearRampToValueAtTime(.055,start+.015);
          gain.gain.exponentialRampToValueAtTime(.001,start+.17);
          oscillator.connect(gain);gain.connect(audio.destination);
          oscillator.start(start);oscillator.stop(start+.18);
        });
      }catch{}
    }
    function showReward(message,detail) {
      clearTimeout(toastTimer);
      document.querySelector('.quest-reward-toast')?.remove();
      const toast=document.createElement('div');
      toast.className='quest-reward-toast';
      toast.setAttribute('role','status');
      const image=document.createElement('img');
      image.src=MASCOT; image.alt=''; image.width=50; image.height=50;
      const body=document.createElement('div');
      const title=document.createElement('strong');title.textContent=message;
      const description=document.createElement('span');description.textContent=detail;
      body.append(title,description);toast.append(image,body);document.body.append(toast);
      if(!reduced()&&toast.animate)toast.animate([
        {opacity:0,transform:'translate(-50%,14px) scale(.95)'},
        {opacity:1,transform:'translate(-50%,0) scale(1)'}
      ],{duration:280,easing:'cubic-bezier(.2,.8,.2,1)'});
      toastTimer=setTimeout(()=>toast.remove(),3000);
    }
    function reward(attempts) {
      game=mergeGame(game,readSaved());
      const result=awardAttempts(game,attempts,today());
      game=result.game;persist();updateStats();
      if(result.goalReached) {
        showReward('ภารกิจวันนี้สำเร็จ!','ฝึกครบ 5 ข้อ ได้โบนัส 20 XP · รวมรอบนี้ +'+result.gain+' XP');
        playSound('goal');
      } else if(result.gain>0) {
        showReward('ตอบถูกแล้ว! +'+result.gain+' XP','เก็บความเข้าใจเพิ่มอีกข้อแล้ว');
        playSound('correct');
      } else if(attempts.length===1&&!attempts[0].correct) {
        showReward('อีกนิดเดียว ลองดูเหตุผลกัน','ข้อนี้นับในเป้าหมายฝึกวันนี้แล้ว กลับมาฝึกซ้ำได้');
      }
      return result.gain;
    }
    function makeHUD() {
      const hud=document.createElement('div');
      hud.className='quest-hud';hud.setAttribute('aria-label','ความคืบหน้าภารกิจ');
      for(const [key,title] of [['star','XP'],['fire','วันต่อเนื่อง'],['goal','ฝึกวันนี้']]){
        const item=document.createElement('div');
        item.className='quest-stat '+(key==='fire'?'streak':key==='goal'?'goal':'');
        item.innerHTML=icon(key);
        const value=document.createElement('b');value.dataset.questStat=key;
        const label=document.createElement('span');label.textContent=title;
        item.append(value,label);hud.append(item);
      }
      const sound=document.createElement('button');
      sound.type='button';sound.className='quest-sound';sound.dataset.questSound='';
      sound.addEventListener('click',()=>{
        game=mergeGame(game,readSaved());game.sound=!game.sound;
        persist();updateStats();if(game.sound)playSound('correct');
      });
      hud.append(sound);
      return hud;
    }
    function updateStats() {
      const day=today();
      const count=Math.min(DAILY_GOAL,game.days[day]?.length||0);
      for(const el of main.querySelectorAll('[data-quest-stat]')){
        const values={star:totalXP(game),fire:currentStreak(game,day),goal:count+' / '+DAILY_GOAL};
        el.textContent=values[el.dataset.questStat];
      }
      const sound=main.querySelector('[data-quest-sound]');
      if(sound){
        sound.innerHTML=icon('sound')+(game.sound?'เสียงเปิด':'เปิดเสียง');
        sound.setAttribute('aria-pressed',String(game.sound));
        sound.setAttribute('aria-label',game.sound?'ปิดเสียงตอบถูก':'เปิดเสียงตอบถูก');
      }
      for(const el of main.querySelectorAll('[data-quest-count]'))el.textContent=count+' / '+DAILY_GOAL;
      for(const meter of main.querySelectorAll('[data-quest-meter]')){
        meter.style.width=(count/DAILY_GOAL*100)+'%';
        meter.parentElement.setAttribute('aria-valuenow',String(count));
      }
      const status=main.querySelector('[data-quest-goal-text]');
      if(status)status.textContent=count>=DAILY_GOAL?'สำเร็จแล้ว! โบนัส 20 XP เข้าแล้ว':'ฝึกตอบ 5 ข้อวันนี้ รับโบนัส 20 XP';
      const level=main.querySelector('[data-quest-level]');
      if(level)level.textContent='Level '+(Math.floor(totalXP(game)/100)+1);
      const nextLevel=main.querySelector('[data-quest-next-level]');
      if(nextLevel)nextLevel.textContent='อีก '+(100-totalXP(game)%100)+' XP ถึงระดับถัดไป';
      const local=main.querySelector('[data-quest-local]');
      if(local)local.textContent=writable?'แต้มและสถิติจำในเบราว์เซอร์นี้ · วันใหม่เริ่มเที่ยงคืนเวลาไทย':'เบราว์เซอร์ไม่ให้บันทึก แต้มรอบนี้อยู่เฉพาะหน้านี้';
    }
    function missionPanel(){
      const aside=document.createElement('aside');aside.className='quest-missions';
      aside.setAttribute('aria-label','ภารกิจและแต้มของคุณ');
      const mission=document.createElement('section');mission.className='quest-mission';
      mission.innerHTML='<h3>ภารกิจประจำวัน</h3><div class="quest-count" data-quest-count></div><p data-quest-goal-text></p><div class="quest-meter" role="progressbar" aria-label="เป้าหมายฝึก 5 ข้อ" aria-valuemin="0" aria-valuemax="5"><span data-quest-meter></span></div><a class="btn primary" href="#/practice">เริ่มฝึกวันนี้</a>';
      const level=document.createElement('section');level.className='quest-mission level-panel';
      level.innerHTML='<div class="quest-level"><div class="quest-level-medal" aria-hidden="true">★</div><div><strong data-quest-level></strong><small data-quest-next-level></small></div></div><p style="margin-top:18px">ตอบถูกครั้งแรกข้อละ 10 XP<br>ฝึกครบ 5 ข้อต่อวัน โบนัส 20 XP</p><p class="quest-local" data-quest-local></p>';
      aside.append(mission,level);return aside;
    }
    function connectPath(){
      const board=main.querySelector('.quest-board');if(!board)return;
      const svg=board.querySelector('.quest-trail');
      const road=board.querySelector('.quest-road');
      const box=board.getBoundingClientRect();
      if(!box.width||!box.height)return;
      svg.setAttribute('viewBox','0 0 '+box.width+' '+box.height);
      const points=[...road.querySelectorAll('.num')].map(node=>{
        const rect=node.getBoundingClientRect();return [rect.left-box.left+rect.width/2,rect.top-box.top+rect.height/2];
      });
      if(points.length<2)return;
      let path='M '+points[0].join(' ');
      for(let i=1;i<points.length;i++){
        const [x,y]=points[i-1],[nextX,nextY]=points[i],middle=(y+nextY)/2;
        path+=' C '+x+' '+middle+', '+nextX+' '+middle+', '+nextX+' '+nextY;
      }
      const line=svg.firstElementChild;
      line.setAttribute('d',path);
    }
    function queuePath(){
      cancelAnimationFrame(redrawFrame);redrawFrame=requestAnimationFrame(connectPath);
    }
    function decorateOverview(){
      const hero=main.querySelector('.hero'),grid=main.querySelector('.chapter-grid');
      if(!hero||!grid||main.querySelector('.quest-layout'))return;
      const art=hero.querySelector('.hero-art');
      if(art){
        art.replaceChildren();
        const figure=document.createElement('figure');figure.className='quest-mascot';
        const speech=document.createElement('figcaption');speech.className='quest-speech';speech.textContent='วันนี้มาฝึกด้วยกันสัก 5 ข้อ!';
        const image=document.createElement('img');image.src=MASCOT;image.alt='Bit หุ่นยนต์สวิตช์เครือข่าย ชูนิ้วให้กำลังใจ';image.width=235;image.height=235;image.decoding='async';
        figure.append(speech,image);art.append(figure);
      }
      const heading=main.querySelector('.section-heading h2');
      if(heading)heading.textContent='เส้นทางภารกิจ';
      let done=[];
      try{done=JSON.parse(localStorage.getItem('network-final-01076040-v1'))?.done||[];}catch{}
      const layout=document.createElement('div');layout.className='quest-layout';
      const board=document.createElement('section');board.className='quest-board';board.setAttribute('aria-label','เลือกบทเรียนตามเส้นทาง');
      const trail=document.createElementNS('http://www.w3.org/2000/svg','svg');
      trail.classList.add('quest-trail');trail.setAttribute('aria-hidden','true');
      const line=document.createElementNS('http://www.w3.org/2000/svg','path');
      line.setAttribute('fill','none');line.setAttribute('stroke','var(--line)');line.setAttribute('stroke-width','4');line.setAttribute('stroke-dasharray','9 9');line.setAttribute('stroke-linecap','round');
      trail.append(line);
      const road=document.createElement('ol');road.className='quest-road';
      const cards=[...grid.querySelectorAll('.chapter-card')];
      let nextFound=false;
      cards.forEach(card=>{
        const chapter=Number(card.getAttribute('href')?.match(/chapter\/(\d+)/)?.[1]);
        const step=document.createElement('li');step.className='quest-step';
        if(done.includes(chapter))step.classList.add('is-done');
        else if(!nextFound){nextFound=true;step.classList.add('is-next');}
        step.append(card);
        if(chapter){
          const quiz=document.createElement('button');quiz.type='button';quiz.className='quest-quiz';quiz.dataset.start=String(chapter);
          quiz.textContent='ฝึก 15 ข้อ';quiz.setAttribute('aria-label','ฝึกข้อสอบบท '+chapter+' จำนวน 15 ข้อ');
          step.append(quiz);
        }
        road.append(step);
      });
      board.append(trail,road);layout.append(board,missionPanel());grid.replaceWith(layout);
      routeSizer?.disconnect();
      if('ResizeObserver' in window){routeSizer=new ResizeObserver(queuePath);routeSizer.observe(board);}
      queuePath();
    }
    function processAnswer(){
      if(!pending)return;
      const action=pending;pending=null;
      if(action.type==='answer'){
        const panel=main.querySelector('.question-panel');
        const feedback=panel?.querySelector('.feedback');
        if(!feedback||questionID(panel.querySelector('h2')?.textContent)!==action.id)return;
        const correct=!feedback.classList.contains('wrong');
        const gain=reward([{id:action.id,correct}]);
        if(gain>0){
          const label=document.createElement('div');label.className='quest-answer-reward';label.textContent='+'+gain+' XP';
          feedback.append(label);
        }
      }else if(main.querySelector('.result-head')){
        const attempts=[...main.querySelectorAll('.review-item')].map(item=>({
          id:questionID(item.querySelector('summary')?.textContent),
          correct:!!item.querySelector('.mark.good')
        }));
        if(attempts.length)reward(attempts);
      }
    }
    function refresh(){
      frame=0;processAnswer();
      if(!main.querySelector('.quest-hud'))main.prepend(makeHUD());
      decorateOverview();updateStats();
    }
    const queue=()=>{if(!frame)frame=requestAnimationFrame(refresh);};
    document.addEventListener('click',event=>{
      const control=event.target.closest('[data-check],[data-finish]');
      if(!control||control.disabled)return;
      if(control.hasAttribute('data-check')){
        const panel=main.querySelector('.question-panel');
        if(!panel?.querySelector('.option.selected'))return;
        pending={type:'answer',id:questionID(panel.querySelector('h2')?.textContent)};
      }else pending={type:'exam'};
      queue();
    },true);
    new MutationObserver(queue).observe(main,{childList:true});
    window.addEventListener('resize',queuePath);
    window.addEventListener('storage',event=>{
      if(event.key!==GAME_KEY)return;
      const before=JSON.stringify(game);
      game=mergeGame(game,readSaved());
      if(JSON.stringify(game)!==before)persist();
      updateStats();
    });
    document.addEventListener('visibilitychange',()=>{if(!document.hidden){game=mergeGame(game,readSaved());updateStats();}});
    refresh();
  },{once:true});
})();

